360	func TestInvalidConfig(t *testing.T) {
361		cases := []struct {
362			name    string
363			src     string
364			want    string // reason substring
365			located bool   // whether the reason should locate the route
366		}{
367			{"not json", `{not json`, "not valid JSON", false},
368			{"empty id", `{"routes":[{"id":"","methods":["GET"],"pathPrefix":"/a","upstream":"http://h"}]}`, "id must be non-empty", true},
369			{"duplicate id", `{"routes":[
370			  {"id":"x","methods":["GET"],"pathPrefix":"/a","upstream":"http://h1"},
371			  {"id":"x","methods":["GET"],"pathPrefix":"/b","upstream":"http://h2"}]}`, "duplicate id", true},
372			{"empty methods", `{"routes":[{"id":"x","methods":[],"pathPrefix":"/a","upstream":"http://h"}]}`, "non-empty", true},
373			{"bad method token", `{"routes":[{"id":"x","methods":["GE T"],"pathPrefix":"/a","upstream":"http://h"}]}`, "invalid method", true},
374			{"prefix not absolute", `{"routes":[{"id":"x","methods":["GET"],"pathPrefix":"a","upstream":"http://h"}]}`, "start with /", true},
375			{"prefix trailing slash", `{"routes":[{"id":"x","methods":["GET"],"pathPrefix":"/a/","upstream":"http://h"}]}`, "end with /", true},
376			{"root trailing slash allowed", `{"routes":[{"id":"x","methods":["GET"],"pathPrefix":"/","upstream":"http://h"}]}`, "", true},
377			{"prefix with query", `{"routes":[{"id":"x","methods":["GET"],"pathPrefix":"/a?x=1","upstream":"http://h"}]}`, "query string or fragment", true},
378			{"prefix with fragment", `{"routes":[{"id":"x","methods":["GET"],"pathPrefix":"/a#f","upstream":"http://h"}]}`, "query string or fragment", true},
379			{"prefix bad percent escape", `{"routes":[{"id":"x","methods":["GET"],"pathPrefix":"/a%2","upstream":"http://h"}]}`, "percent escape", true},
380			{"upstream relative", `{"routes":[{"id":"x","methods":["GET"],"pathPrefix":"/a","upstream":"/path"}]}`, "absolute http or https", true},
381			{"upstream wrong scheme", `{"routes":[{"id":"x","methods":["GET"],"pathPrefix":"/a","upstream":"ftp://h"}]}`, "absolute http or https", true},
382			{"upstream missing host", `{"routes":[{"id":"x","methods":["GET"],"pathPrefix":"/a","upstream":"http:///path"}]}`, "include a host", true},
383			{"upstream with query", `{"routes":[{"id":"x","methods":["GET"],"pathPrefix":"/a","upstream":"http://h?x=1"}]}`, "query string or fragment", true},
384			{"upstream with fragment", `{"routes":[{"id":"x","methods":["GET"],"pathPrefix":"/a","upstream":"http://h#f"}]}`, "query string or fragment", true},
385		}
386		for _, tc := range cases {
387			t.Run(tc.name, func(t *testing.T) {
388				_, f := ParseConfig([]byte(tc.src))
389				if tc.want == "" {
390					if f != nil {
391						t.Fatalf("unexpected failure: %+v", f)
392					}
393					return
394				}
395				if f == nil {
396					t.Fatalf("expected invalid_config containing %q", tc.want)
397				}
398				if f.Code != "invalid_config" {
399					t.Fatalf("code = %q, want invalid_config", f.Code)
400				}
401				if !strings.Contains(f.Reason, tc.want) {
402					t.Fatalf("reason = %q, want substring %q", f.Reason, tc.want)
403				}
404				if tc.located && !strings.Contains(f.Reason, "route ") {
405					t.Fatalf("reason = %q should locate the route", f.Reason)
406				}
407			})
408		}
409	}
