459				want:      []string{"route 1", "id must be a string"},
460				forbidden: []string{"(id "},
461			},
462			{
463				name:      "id is an object",
464				src:       `{"routes":[{"id":{"v":1},"methods":["GET"],"pathPrefix":"/a","upstream":"http://h"}]}`,
465				want:      []string{"route 1", "id must be a string"},
466				forbidden: []string{"(id "},
467			},
468			{
469				name: "pathPrefix is a number, id written after it",
470				src:  `{"routes":[{"methods":["GET"],"pathPrefix":1,"id":"orders","upstream":"http://o"}]}`,
471				want: []string{"route 1", `"orders"`, "pathPrefix must be a string"},
472			},
473			{
474				name: "upstream is a boolean, id written after it",
475				src:  `{"routes":[{"methods":["GET"],"pathPrefix":"/a","upstream":true,"id":"orders"}]}`,
476				want: []string{"route 1", `"orders"`, "upstream must be a string"},
477			},
478			{
479				name: "routes entry is not an object",
480				src:  `{"routes":[42]}`,
481				want: []string{"route 1", "route entry must be a JSON object"},
482			},
483		}
484		for _, tc := range cases {
485			t.Run(tc.name, func(t *testing.T) {
486				_, f := ParseConfig([]byte(tc.src))
487				if f == nil {
488					t.Fatalf("expected invalid_config")
489				}
490				if f.Code != "invalid_config" {
491					t.Fatalf("code = %q, want invalid_config", f.Code)
492				}
493				if strings.Contains(f.Reason, "not valid JSON") {
494					t.Fatalf("field type error must not be described as a JSON syntax failure: %q", f.Reason)
495				}
496				for _, want := range tc.want {
497					if !strings.Contains(f.Reason, want) {
498						t.Fatalf("reason = %q, want substring %q", f.Reason, want)
499					}
500				}
501				for _, bad := range tc.forbidden {
502					if strings.Contains(f.Reason, bad) {
503						t.Fatalf("reason = %q must not contain %q", f.Reason, bad)
504					}
505				}
506			})
507		}
508	
509		// Broken JSON syntax stays a parse failure and never gets a guessed
510		// route position, even when the corruption is inside the routes array.
511		for _, src := range []string{`{not json`, `{"routes": [{"id":"x"} broken`} {
512			_, f := ParseConfig([]byte(src))
513			if f == nil || f.Code != "invalid_config" {
514				t.Fatalf("got %+v, want invalid_config for %q", f, src)
515			}
516			if !strings.Contains(f.Reason, "not valid JSON") {
517				t.Fatalf("reason = %q, want a JSON parse failure", f.Reason)
518			}
519			if strings.Contains(f.Reason, "route 1") {
520				t.Fatalf("syntax failure must not guess a route position: %q", f.Reason)
521			}
522		}
523	
524		// Fixing the second route's methods lets the request resolve normally,
525		// including through the first route it originally matched.
526		cfg := mustConfig(t, `{"routes":[
527		  {"id":"api","methods":["GET"],"pathPrefix":"/api","upstream":"http://api.internal/v1"},
528		  {"id":"orders","methods":["GET"],"pathPrefix":"/api/orders","upstream":"http://orders.internal"}
529		]}`)
530		res := resolveJSON(t, cfg, `{"method":"GET","target":"/api/items"}`)
531		if res.RouteID != "api" || res.UpstreamURL != "http://api.internal/v1/items" {
532			t.Fatalf("got %+v, want api / http://api.internal/v1/items", res)
533		}
534	}
